      "@type": "FAQPage",
      "@id": "https://www.stselectronicrecyclinginc.com/bakersfield-ca#faqpage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "What certifications do you hold?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS supports NIST SP 800-88 Rev. 2 media sanitization, HIPAA 45 CFR §164.312 technical safeguards, and DoD 5220.22-M destruction methods for Bakersfield clients. Documentation includes chain of custody files, serial tracking, and certificates that support audits. Healthcare, education, and public-sector IT teams use those records during OCR or board reviews. Pickup paperwork starts in Kern County, and destruction records typically follow within 48 hours of processing."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Free pickup for qualifying volumes is available across Bakersfield and greater Kern County, including Oildale, Rosedale, and downtown business offices. Commercial routes also cover Delano, Wasco, Shafter, Taft, Arvin, and Tehachapi by appointment. Organizations searching for electronics recycling near me throughout Bakersfield find STS provides free pickup in Oildale, Rosedale, and all Kern County locations."
          }
        },
        {
          "@type": "Question",
          "name": "Is pickup really free?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is typically free for qualifying volumes of computers, servers, printers, and displays from Bakersfield businesses, schools, and public agencies. Written quotes list any exceptions before a crew is scheduled, with no hidden pickup fees."
          }
        },
        {
          "@type": "Question",
          "name": "How long does pickup take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Generally, Bakersfield organizations receive same-week pickup after we receive a completed inventory worksheet and parking notes. Crew on-site time depends on volume, dock access, and whether drives require witnessed destruction before transport."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Every Bakersfield pickup includes chain of custody records and a Certificate of Destruction, typically within 48 hours of processing. Serial-level reports support internal audits and regulator inquiries for IT teams. Corporate IT Directors typically expect detailed certificates of destruction for audit reviews, included in every STS service engagement."
          }
        },
        {
          "@type": "Question",
          "name": "What happens to my equipment after pickup?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Collected equipment is tagged, scanned, sorted, and prepared for transport from Bakersfield to our 200,000 sq ft processing operation. Reusable assets may be remarketed, and remaining materials enter downstream recovery with full chain of custody."
          }
        }
      ]
